#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

using namespace Eigen;

int main() {
    double coords[6][3] = {
        {0,0,0},{1,0,0},{0,1,0},{0,0,1},{1,0,1},{0,1,1}
    };
    double E = 200e9, nu = 0.3;
    double GG = E/(2*(1+nu));

    Matrix<double,6,6> D = Matrix<double,6,6>::Zero();
    double temp1 = (1.0+nu)*(1.0-2.0*nu);
    double g1 = E*(1.0-nu)/temp1;
    double g2 = E*nu/temp1;
    D(0,0)=g1; D(1,1)=g1; D(2,2)=g1;
    D(0,1)=g2; D(0,2)=g2;
    D(1,0)=g2; D(1,2)=g2;
    D(2,0)=g2; D(2,1)=g2;
    D(3,3)=GG; D(4,4)=GG; D(5,5)=GG;

    Matrix<double,18,18> K = Matrix<double,18,18>::Zero();

    // 3x3x3 Gauss points on triangle (use collapsed coords)
    // Use triangle quadrature points for r,s and Gauss for t
    // Triangle: 3-point rule
    double tri_pts[3][2] = {{1.0/6,1.0/6},{2.0/3,1.0/6},{1.0/6,2.0/3}};
    double tri_w[3] = {1.0/6,1.0/6,1.0/6}; // weights sum to 1/2
    // Gauss for t: 2-point
    double g_pts[2] = {-1.0/sqrt(3.0), 1.0/sqrt(3.0)};
    double g_w[2] = {1.0, 1.0};

    for (int a = 0; a < 3; ++a) {
        double r = tri_pts[a][0], s = tri_pts[a][1];
        for (int b = 0; b < 2; ++b) {
            double t = 0.5*(g_pts[b]+1.0); // map to [0,1]
            double wt = tri_w[a] * g_w[b] * 0.5; // jacobian of t mapping

            // Shape functions
            double N[6];
            N[0] = (1-r-s)*(1-t);
            N[1] = r*(1-t);
            N[2] = s*(1-t);
            N[3] = (1-r-s)*t;
            N[4] = r*t;
            N[5] = s*t;

            // Derivatives w.r.t. r,s,t
            double dNdr[6] = {-(1-t), (1-t), 0, -t, t, 0};
            double dNds[6] = {-(1-t), 0, (1-t), -t, 0, t};
            double dNdt[6] = {-(1-r-s), -r, -s, (1-r-s), r, s};

            // Jacobian
            Matrix3d J = Matrix3d::Zero();
            for (int i = 0; i < 6; ++i) {
                J(0,0) += dNdr[i]*coords[i][0];
                J(0,1) += dNdr[i]*coords[i][1];
                J(0,2) += dNdr[i]*coords[i][2];
                J(1,0) += dNds[i]*coords[i][0];
                J(1,1) += dNds[i]*coords[i][1];
                J(1,2) += dNds[i]*coords[i][2];
                J(2,0) += dNdt[i]*coords[i][0];
                J(2,1) += dNdt[i]*coords[i][1];
                J(2,2) += dNdt[i]*coords[i][2];
            }
            double detJ = J.determinant();
            Matrix3d Jinv = J.inverse();

            // B matrix 6x18
            Matrix<double,6,18> B = Matrix<double,6,18>::Zero();
            for (int i = 0; i < 6; ++i) {
                Vector3d dN;
                dN << dNdr[i], dNds[i], dNdt[i];
                Vector3d dNxyz = Jinv * dN;
                double bx = dNxyz(0), by = dNxyz(1), bz = dNxyz(2);
                int c = 3*i;
                B(0,c+0) = bx;
                B(1,c+1) = by;
                B(2,c+2) = bz;
                B(3,c+0) = by; B(3,c+1) = bx;
                B(4,c+1) = bz; B(4,c+2) = by;
                B(5,c+0) = bz; B(5,c+2) = bx;
            }
            K += wt * detJ * B.transpose() * D * B;
        }
    }

    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 18; ++i) {
        std::cout << "[";
        for (int j = 0; j < 18; ++j) {
            std::cout << std::scientific << std::setprecision(6) << K(i,j);
            if (j < 17) std::cout << ",";
        }
        std::cout << "]";
        if (i < 17) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
